-- ADR056. Store normal private contact details only within the existing authorized tenant scope.
DO $guard$ BEGIN IF (SELECT encode(sha256(convert_to(pg_get_constraintdef(oid),'UTF8')),'hex') FROM pg_constraint WHERE conrelid='app.private_contact_data'::regclass AND conname='private_contact_data_email_check') IS DISTINCT FROM 'e6e96a8a097d273eb7de5add2d2a725466e436a252ee7fdc09975433fff54533' THEN RAISE EXCEPTION 'Real-use prerequisite constraint differs: private_contact_data.email';END IF;END $guard$;
ALTER TABLE app.private_contact_data DROP CONSTRAINT private_contact_data_email_check;
ALTER TABLE app.private_contact_data ADD CONSTRAINT private_contact_data_email_check CHECK(CASE WHEN app.tenant_is_synthetic(tenant_id) THEN email ~ '^[^@]+@example[.]invalid$' ELSE email ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' END);
DO $guard$ BEGIN IF (SELECT encode(sha256(convert_to(pg_get_constraintdef(oid),'UTF8')),'hex') FROM pg_constraint WHERE conrelid='app.public_identifier'::regclass AND conname='public_identifier_domain_check') IS DISTINCT FROM 'f08db34ca988f16ec1ad407c33f6c012045f6124a0e00c62f0360fce8421d643' THEN RAISE EXCEPTION 'Real-use prerequisite constraint differs: public_identifier.domain';END IF;END $guard$;
ALTER TABLE app.public_identifier DROP CONSTRAINT public_identifier_domain_check;
ALTER TABLE app.public_identifier ADD CONSTRAINT public_identifier_domain_check CHECK(CASE WHEN synthetic THEN domain ~ '^([a-z0-9]([a-z0-9-]*[a-z0-9])?[.])*example[.]invalid$' ELSE length(domain)<=253 AND domain ~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?[.])+[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$' END);
